# Complete drug workups ("drug cards") the question bank shows on every linked case.
# Each section is plain text with **bold**; every number carries its source mark (✅✅ two sources, ✅ one, ⚠️ verify).
import json, os

def card(title, sections, sources):
    return {'title': title, 'sections': sections, 'sources': sources}

MG_LABEL_VIAL = {'t': 'Magnesium Sulfate Injection USP 50% vial, prescribing information (Pfizer)', 'url': 'https://www.pfizermedical.com/magnesium-sulfate-injection-usp-vial/dosage-admin', 'mark': '✅'}
MG_LABEL_BAG = {'t': 'Magnesium Sulfate in 5% Dextrose Injection, prescribing information (MedLibrary)', 'url': 'https://medlibrary.org/lib/rx/meds/magnesium-sulfate-in-dextrose/', 'mark': '✅'}
ACOG_ECL = {'t': 'ACOG District II: Eclampsia checklist (Safe Motherhood Initiative)', 'url': 'https://www.scdhhs.gov/sites/default/files/ACOG-District-II-Checklist-Eclampsia.pdf', 'mark': '✅'}
PB222 = {'t': 'ACOG Practice Bulletin 222: Gestational hypertension and preeclampsia (2020)', 'url': 'https://doi.org/10.1097/AOG.0000000000003891', 'mark': '✅'}
CO767 = {'t': 'ACOG Committee Opinion 767: severe hypertension in pregnancy and postpartum (2019)', 'url': 'https://doi.org/10.1097/AOG.0000000000003075', 'mark': '✅'}
CO455 = {'t': 'ACOG Committee Opinion 455: magnesium for fetal neuroprotection', 'url': 'https://doi.org/10.1097/AOG.0b013e3181d4ffa5', 'mark': '✅'}
